command:
set -euo pipefail
D=$(mktemp -d /tmp/omega777-postmerge.XXXXXX)
trap 'rm -rf "$D"' EXIT
git clone -q https://github.com/gschaidergabriel/frankenstein.git "$D/r"
cd "$D/r"
git checkout -q ffcb92eadfd15bd55c736c1d9ab1be146b460193
echo SOURCE_HEAD=$(git rev-parse HEAD)
python3 -m py_compile scripts/voice_host_777_live_client.py scripts/frankenstein_identity_assembly.py scripts/omega_organ_activity.py
python3 tests/test_voice_host_777_identity.py
python3 tests/test_omega_organ_activity.py
python3 -m pytest -q tests/test_voice_omega_retrieval.py tests/test_frankenstein_identity_assembly.py tests/test_voice777_installer_convergence.py
echo VOICE_EXECSTART=$(systemctl --user show frankenstein-gespraechsmodus.service -p ExecStart --value 2>/dev/null || true)
echo CLIENT_EXECSTART=$(systemctl --user show frankenstein-chatgpt-client.service -p ExecStart --value 2>/dev/null || true)
echo VOICE_ACTIVE=$(systemctl --user is-active frankenstein-gespraechsmodus.service 2>/dev/null || true)
echo CLIENT_ACTIVE=$(systemctl --user is-active frankenstein-chatgpt-client.service 2>/dev/null || true)
echo VOICE_MAINPID=$(systemctl --user show frankenstein-gespraechsmodus.service -p MainPID --value 2>/dev/null || true)
echo CLIENT_MAINPID=$(systemctl --user show frankenstein-chatgpt-client.service -p MainPID --value 2>/dev/null || true)
for f in "$HOME/.local/lib/frankenstein/scripts/voice_777_runtime.py" "$HOME/.local/lib/frankenstein/scripts/voice_host_777_live_client.py" "$HOME/.local/lib/frankenstein/scripts/omega_organ_activity.py"; do if [ -f "$f" ]; then sha256sum "$f"; else echo MISSING:$f; fi; done
echo OMEGA_POSTMERGE_LIVE_READBACK_PASS
